// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/// @title TimelockVault - A timelock-based token vault with delegation
/// @notice Allows users to lock tokens with time-based withdrawal restrictions
/// @dev Uses checkpoint-based balance tracking for gas efficiency
contract TimelockVault {
    struct Lock {
        uint128 amount;
        uint64 unlockTime;
        uint64 delegatedUntil;
    }

    struct Checkpoint {
        uint64 fromBlock;
        uint192 votes;
    }

    mapping(address => Lock[]) public locks;
    mapping(address => Checkpoint[]) public checkpoints;
    mapping(address => address) public delegates;
    mapping(address => uint256) public nonces;

    address public immutable token;
    address public governance;
    uint256 public totalLocked;
    uint256 public constant MAX_LOCK_DURATION = 365 days;
    uint256 public constant MIN_LOCK_DURATION = 1 days;

    event Locked(address indexed user, uint256 amount, uint256 unlockTime);
    event Withdrawn(address indexed user, uint256 lockIndex, uint256 amount);
    event DelegateChanged(address indexed delegator, address indexed toDelegate);
    event GovernanceTransferred(address indexed oldGov, address indexed newGov);

    modifier onlyGovernance() {
        require(msg.sender == governance, "not governance");
        _;
    }

    constructor(address _token, address _governance) {
        require(_token != address(0) && _governance != address(0), "zero addr");
        token = _token;
        governance = _governance;
    }

    /// @notice Lock tokens with a specified duration
    /// @param amount The amount of tokens to lock
    /// @param duration The lock duration in seconds
    function lock(uint128 amount, uint256 duration) external {
        require(amount > 0, "zero amount");
        require(duration >= MIN_LOCK_DURATION && duration <= MAX_LOCK_DURATION, "invalid duration");

        uint64 unlockTime = uint64(block.timestamp + duration);
        locks[msg.sender].push(Lock({
            amount: amount,
            unlockTime: unlockTime,
            delegatedUntil: 0
        }));

        totalLocked += amount;
        _moveVotingPower(address(0), _effectiveDelegate(msg.sender), amount);

        // Transfer tokens in
        _safeTokenCall(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", msg.sender, address(this), uint256(amount))
        );

        emit Locked(msg.sender, amount, unlockTime);
    }

    /// @notice Withdraw unlocked tokens
    /// @param lockIndex The index of the lock to withdraw
    function withdraw(uint256 lockIndex) external {
        require(lockIndex < locks[msg.sender].length, "invalid index");
        Lock storage userLock = locks[msg.sender][lockIndex];
        require(block.timestamp >= userLock.unlockTime, "still locked");
        require(userLock.amount > 0, "already withdrawn");

        uint128 amount = userLock.amount;
        userLock.amount = 0;
        totalLocked -= amount;

        _moveVotingPower(_effectiveDelegate(msg.sender), address(0), amount);

        _safeTokenCall(
            abi.encodeWithSignature("transfer(address,uint256)", msg.sender, uint256(amount))
        );

        emit Withdrawn(msg.sender, lockIndex, amount);
    }

    /// @dev Performs a low-level token call and validates both the call success
    ///      and the ABI-returned boolean (if any). Reverts if the token has no
    ///      code or returns false.
    function _safeTokenCall(bytes memory data) internal {
        require(token.code.length > 0, "token not contract");
        (bool success, bytes memory returndata) = token.call(data);
        require(success, "transfer failed");
        if (returndata.length > 0) {
            require(abi.decode(returndata, (bool)), "token returned false");
        }
    }

    /// @notice Delegate voting power to another address
    function delegate(address to) external {
        require(to != address(0), "zero delegate");
        address oldDelegate = _effectiveDelegate(msg.sender);
        delegates[msg.sender] = to;
        uint256 votingPower = _getVotingPower(msg.sender);
        _moveVotingPower(oldDelegate, to, votingPower);
        emit DelegateChanged(msg.sender, to);
    }

    /// @notice Get current votes for an account
    function getCurrentVotes(address account) external view returns (uint256) {
        uint256 nCheckpoints = checkpoints[account].length;
        return nCheckpoints > 0 ? checkpoints[account][nCheckpoints - 1].votes : 0;
    }

    /// @notice Get votes at a specific block number
    /// @param account The address to query
    /// @param blockNumber The block number to query at
    function getPriorVotes(address account, uint256 blockNumber) external view returns (uint256) {
        require(blockNumber < block.number, "not yet determined");
        return _getPriorVotes(account, blockNumber);
    }

    /// @notice Emergency extend lock duration (governance only)
    /// @param user The user whose lock to extend
    /// @param lockIndex The lock index
    /// @param additionalTime Additional time to add
    function emergencyExtendLock(address user, uint256 lockIndex, uint256 additionalTime) external onlyGovernance {
        require(lockIndex < locks[user].length, "invalid index");
        require(additionalTime <= MAX_LOCK_DURATION, "too long");
        Lock storage userLock = locks[user][lockIndex];
        require(userLock.amount > 0, "empty lock");
        // Safe: checked addition prevents overflow
        uint64 newUnlockTime = userLock.unlockTime + uint64(additionalTime);
        require(newUnlockTime >= userLock.unlockTime, "overflow");
        userLock.unlockTime = newUnlockTime;
    }

    /// @notice Batch query for voting power calculation
    /// @param accounts Array of accounts to query
    /// @param weights Array of weight multipliers (basis points)
    /// @return totalWeightedVotes The sum of weighted votes
    function batchWeightedVotes(address[] calldata accounts, uint16[] calldata weights) external view returns (uint256 totalWeightedVotes) {
        require(accounts.length == weights.length, "length mismatch");
        for (uint256 i = 0; i < accounts.length; i++) {
            uint256 nCheckpoints = checkpoints[accounts[i]].length;
            uint256 votes = nCheckpoints > 0 ? checkpoints[accounts[i]][nCheckpoints - 1].votes : 0;
            totalWeightedVotes += _applyWeight(votes, weights[i]);
        }
    }

    /// @notice Calculate weighted vote contribution
    /// @dev Weight is in basis points (10000 = 100%)
    function _applyWeight(uint256 votes, uint16 weight) internal pure returns (uint256) {
        return (votes * uint256(weight)) / 10000;
    }

    /// @notice Governance proposal execution with quorum check
    /// @param proposalVotes Total votes supporting the proposal
    /// @param quorumBps Quorum threshold in basis points of total locked
    function checkQuorum(uint256 proposalVotes, uint16 quorumBps) external view returns (bool) {
        uint256 quorumVotes = _calculateQuorum(totalLocked, quorumBps);
        return proposalVotes >= quorumVotes;
    }

    /// @dev Calculate quorum threshold
    function _calculateQuorum(uint256 total, uint16 bps) internal pure returns (uint256) {
        return (total * uint256(bps)) / 10000;
    }

    /// @notice Transfer governance role
    function transferGovernance(address newGov) external onlyGovernance {
        require(newGov != address(0), "zero addr");
        emit GovernanceTransferred(governance, newGov);
        governance = newGov;
    }

    /// @notice Extend delegation period for a specific lock
    /// @param lockIndex Index of the lock
    /// @param extensionDuration How long to extend delegation
    function extendDelegation(uint256 lockIndex, uint256 extensionDuration) external {
        require(lockIndex < locks[msg.sender].length, "invalid index");
        require(extensionDuration <= MAX_LOCK_DURATION, "too long");
        Lock storage userLock = locks[msg.sender][lockIndex];
        require(userLock.amount > 0, "empty lock");
        // Safe checked addition in Solidity 0.8.20 default context
        uint64 newDelegatedUntil = userLock.delegatedUntil + uint64(extensionDuration);
        require(newDelegatedUntil >= userLock.delegatedUntil, "overflow");
        userLock.delegatedUntil = newDelegatedUntil;
    }

    // --- Internal functions ---

    function _effectiveDelegate(address account) internal view returns (address) {
        address d = delegates[account];
        return d == address(0) ? account : d;
    }

    function _getVotingPower(address account) internal view returns (uint256) {
        uint256 total = 0;
        Lock[] storage userLocks = locks[account];
        for (uint256 i = 0; i < userLocks.length; i++) {
            total += userLocks[i].amount;
        }
        return total;
    }

    function _moveVotingPower(address from, address to, uint256 amount) internal {
        if (from != address(0) && amount > 0) {
            uint256 nCheckpoints = checkpoints[from].length;
            uint256 oldVotes = nCheckpoints > 0 ? checkpoints[from][nCheckpoints - 1].votes : 0;
            uint256 newVotes = oldVotes - amount;
            _writeCheckpoint(from, nCheckpoints, uint192(newVotes));
        }
        if (to != address(0) && amount > 0) {
            uint256 nCheckpoints = checkpoints[to].length;
            uint256 oldVotes = nCheckpoints > 0 ? checkpoints[to][nCheckpoints - 1].votes : 0;
            uint256 newVotes = oldVotes + amount;
            _writeCheckpoint(to, nCheckpoints, uint192(newVotes));
        }
    }

    function _writeCheckpoint(address account, uint256 nCheckpoints, uint192 newVotes) internal {
        if (nCheckpoints > 0 && checkpoints[account][nCheckpoints - 1].fromBlock == uint64(block.number)) {
            checkpoints[account][nCheckpoints - 1].votes = newVotes;
        } else {
            checkpoints[account].push(Checkpoint(uint64(block.number), newVotes));
        }
    }

    function _getPriorVotes(address account, uint256 blockNumber) internal view returns (uint256) {
        Checkpoint[] storage accountCheckpoints = checkpoints[account];
        uint256 nCheckpoints = accountCheckpoints.length;
        if (nCheckpoints == 0) return 0;
        if (accountCheckpoints[nCheckpoints - 1].fromBlock <= blockNumber) {
            return accountCheckpoints[nCheckpoints - 1].votes;
        }
        if (accountCheckpoints[0].fromBlock > blockNumber) return 0;

        uint256 lower = 0;
        uint256 upper = nCheckpoints - 1;
        while (upper > lower) {
            uint256 center = upper - (upper - lower) / 2;
            if (accountCheckpoints[center].fromBlock <= blockNumber) {
                lower = center;
            } else {
                upper = center - 1;
            }
        }
        return accountCheckpoints[lower].votes;
    }
}
